CREATE TABLE `harddisk_shipments` (
  `id` int(10) UNSIGNED NOT NULL,
  `request_id` int(10) UNSIGNED DEFAULT NULL COMMENT 'อ้างอิงคำขอจาก harddisk_delivery_requests.id',
